def repeat(n):
    def decorator(func):
        def wrapper(*args, **kwargs):
            print(f"{n}번 반복합니다:")
            for _ in range(n):
                func(*args, **kwargs)
        return wrapper
    return decorator

@repeat(3)
def greet(name):
    print(f"Hello, {name}!")

greet("World")
